import{_ as s,H as n,f as e,i as t}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"15 | 查询商品：资源不足有哪些性能表现？","description":"","frontmatter":{},"headers":[{"level":2,"title":"压力场景数据","slug":"压力场景数据","link":"#压力场景数据","children":[]},{"level":2,"title":"先看架构图","slug":"先看架构图","link":"#先看架构图","children":[]},{"level":2,"title":"拆分响应时间","slug":"拆分响应时间","link":"#拆分响应时间","children":[]},{"level":2,"title":"全局监控","slug":"全局监控","link":"#全局监控","children":[]},{"level":2,"title":"定向分析","slug":"定向分析","link":"#定向分析","children":[{"level":3,"title":"ES client请求不均衡","slug":"es-client请求不均衡","link":"#es-client请求不均衡","children":[]},{"level":3,"title":"ES Data CPU使用率高","slug":"es-data-cpu使用率高","link":"#es-data-cpu使用率高","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"课后作业","slug":"课后作业","link":"#课后作业","children":[]}],"relativePath":"高楼的性能工程实战课/15-查询商品：资源不足有哪些性能表现？.md","filePath":"高楼的性能工程实战课/15-查询商品：资源不足有哪些性能表现？.md","lastUpdated":1779822916000}'),p={name:"高楼的性能工程实战课/15-查询商品：资源不足有哪些性能表现？.md"};function i(l,a,c,E,r,o){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="_15-查询商品-资源不足有哪些性能表现" tabindex="-1">15 | 查询商品：资源不足有哪些性能表现？ <a class="header-anchor" href="#_15-查询商品-资源不足有哪些性能表现" aria-label="Permalink to &quot;15 | 查询商品：资源不足有哪些性能表现？&quot;">​</a></h1><p>你好，我是高楼。</p><p>这节课，我们来收拾“查询商品”这个接口。虽然这次的现象同样是TPS低、响应时间长，但是，这个接口走的路径和之前的不一样，所以在分析过程中会有些新鲜的东西，你将看到在资源真的不足的情况下，我们只有增加相应节点的资源才能提升性能。</p><p>在我的项目中，我一直都在讲， <strong>不要轻易给出资源不足的结论。因为但凡有优化的空间，我们都要尝试做优化，而不是直接告诉客户加资源。而给出“增加资源”这个结论，也必须建立在有足够证据的基础上</strong>。在这节课中，你也将看到这一点。</p><p>话不多说，我们直接开始今天的内容。</p><h2 id="压力场景数据" tabindex="-1">压力场景数据 <a class="header-anchor" href="#压力场景数据" aria-label="Permalink to &quot;压力场景数据&quot;">​</a></h2><p>对于查询商品接口，我们第一次试执行性能场景的结果如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/75ef8d040cdbcef4556bbfa7fd7098a2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/75ef8d040cdbcef4556bbfa7fd7098a2.png" alt=""></a></p><p>你看，TPS只有250左右，并且响应时间也明显随着压力的增加而增加了，看起来瓶颈已经出现了，对吧？根据哥的逻辑，下一步就是看架构图啦。</p><h2 id="先看架构图" tabindex="-1">先看架构图 <a class="header-anchor" href="#先看架构图" aria-label="Permalink to &quot;先看架构图&quot;">​</a></h2><p>我们用APM工具来看看这个接口的架构。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/6bcbe3236d91fd7628fa5a6186243870.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/6bcbe3236d91fd7628fa5a6186243870.png" alt=""></a></p><p>你看，从压力机到Gateway服务、到Search服务、再到ES-Client，这个APM工具也只能帮我们到这里了。因为我们用的是ElasticSearch 7来做的搜索服务的支撑，而这个skywalking工具也没有对应的Agent，所以后面并没有配置skywalking。</p><p>在这里，我要多啰嗦几句。现在的APM工具大多是基于应用层来做的，有些运维APM采集的数据会更多一些，但也是响应时间、吞吐量等这样的信息。对于性能分析而言，现在的APM工具有减少排查时间的能力，但是在组件级的细化定位上还有待提高。虽然AI OPS也被提到了台面，但是也没见过哪个公司上了AIOPS产品后，就敢不让人看着。</p><p>总之，从细化分析的角度，我们在定位问题的根本原因时，手头有什么工具就可以用什么工具，即使什么工具都没有，撸日志也是照样能做到的，所以我建议你不要迷信工具，要“迷信”思路。</p><p>下面我们来拆分下这个接口的响应时间，看看这个案例的问题点在哪里。</p><h2 id="拆分响应时间" tabindex="-1">拆分响应时间 <a class="header-anchor" href="#拆分响应时间" aria-label="Permalink to &quot;拆分响应时间&quot;">​</a></h2><p><strong>“在RESAR性能分析逻辑中，拆分响应时间只是一个分析的起点</strong>。”这是我一直在强调的一句话。如果性能工程师连这个都不会做，就只能好好学习天天向上了。</p><p>根据架构图，我们拆分响应时间如下。</p><ul><li>Gateway服务上的响应时间：</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/dc64c9e8ace689c86d6584b64f9f230d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/dc64c9e8ace689c86d6584b64f9f230d.png" alt=""></a></p><ul><li>Search服务上的响应时间：</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/a6dc83d1b51445464d3db3e5421798c9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/a6dc83d1b51445464d3db3e5421798c9.png" alt=""></a></p><ul><li>ES Client的响应时间：</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/0b168cdd73f30b5565c52a6d97b45081.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/0b168cdd73f30b5565c52a6d97b45081.png" alt=""></a></p><p>一层层看过之后，我们发现查询商品这个接口的响应时间消耗在了ES client上面。而在我们这个查询的路径上，在gateway/search服务上，我们并没有做什么复杂的动作。</p><p>既然知道了响应时间消耗在哪里，下面我们就来定位它，看能不能把TPS优化起来。</p><h2 id="全局监控" tabindex="-1">全局监控 <a class="header-anchor" href="#全局监控" aria-label="Permalink to &quot;全局监控&quot;">​</a></h2><p>根据高老师的经验，我们还是从全局监控开始，看全局监控可以让我们更加有的放矢。在分析的过程中，经常有人往下走了几步之后，就开始思维混乱、步伐飘逸。因为数据有很多，所以分析时很容易从一个数据走到不重要的分支上去了。而这时候，如果你心里有全局监控数据，思路就会更清晰，不会在无关的分支上消耗时间。</p><p>回到我们这个例子中，从下面的k8s worker（也就是k8s中的node，在我们的环境中我习惯叫成worker，就是为了体现：在我的地盘，我爱叫啥就叫啥）的数据上来看，似乎没有一个worker的资源使用率是特别高的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/25bb0386561be19b9615a4b0130fe4e5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/25bb0386561be19b9615a4b0130fe4e5.png" alt=""></a></p><p>请你注意，在k8s中看资源消耗，一定不要只看worker这个层面，因为这个层面还不够，一个worker上可能会运行多个pod。从上图来看，由于worker层面没有资源消耗，但是时间又明显是消耗在ES client上的，所以，接下来我们要看一下每一个pod的资源使用情况。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/13f919d42a29f2d37f699036658006f3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/13f919d42a29f2d37f699036658006f3.png" alt=""></a></p><p>咦，有红色。你看，有两个与ES相关的POD，它们的CPU都飘红了，这下可有得玩了。既然是与ES相关的POD，那我们就把ES所有的POD排个序看看。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/624d7bc2fe25f731aa42037d8d9f29bd.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/624d7bc2fe25f731aa42037d8d9f29bd.png" alt=""></a></p><p>从上图的数据来看，有一个ES Client 消耗了67%的CPU，有两个ES Data消耗了99%的CPU，ES本来就是吃CPU的大户，所以我们接下来要着重分析它。</p><p>这里我再说明一点，我们从前面的worker资源使用率一步一步走到这里，在分析方向上是合情合理的，因为这些都是属于我提到的全局监控的内容。</p><h2 id="定向分析" tabindex="-1">定向分析 <a class="header-anchor" href="#定向分析" aria-label="Permalink to &quot;定向分析&quot;">​</a></h2><p>现在我们就来扒一扒ES，看看它在哪个worker节点上。罗列Pod信息如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root&amp;#64;k8s-master-1 ~]# kubectl get pods -o wide | grep elasticsearch</span></span>
<span class="line"><span>elasticsearch-client-0                      1/1     Running   0          6h43m   10.100.230.2     k8s-worker-1   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>elasticsearch-client-1                      1/1     Running   0          6h45m   10.100.140.8     k8s-worker-2   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>elasticsearch-data-0                        1/1     Running   0          7h8m    10.100.18.197    k8s-worker-5   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>elasticsearch-data-1                        1/1     Running   0          7h8m    10.100.5.5       k8s-worker-7   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>elasticsearch-data-2                        1/1     Running   0          7h8m    10.100.251.67    k8s-worker-9   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>elasticsearch-master-0                      1/1     Running   0          7h8m    10.100.230.0     k8s-worker-1   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>elasticsearch-master-1                      1/1     Running   0          7h8m    10.100.227.131   k8s-worker-6   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>elasticsearch-master-2                      1/1     Running   0          7h8m    10.100.69.206    k8s-worker-3   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]#</span></span></code></pre></div><p>现在就比较清晰了，可以看到，在整个namespace中有两个ES client，三个ES data，三个ES master。</p><p>我们来画一个细一点的架构图，以便在脑子里记下这个逻辑：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/2e8a4fe8b5e214a8463d918dea8cyy0f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/2e8a4fe8b5e214a8463d918dea8cyy0f.jpg" alt=""></a></p><p>再结合我们在全局分析中看到的资源使用率图，现在判断至少有两个问题：</p><ol><li>ES client请求不均衡；</li><li>ES data CPU 高。</li></ol><p>下面我们一个一个来分析。</p><h3 id="es-client请求不均衡" tabindex="-1">ES client请求不均衡 <a class="header-anchor" href="#es-client请求不均衡" aria-label="Permalink to &quot;ES client请求不均衡&quot;">​</a></h3><p>从上面的架构图中可以看到，search服务连两个ES client，但是只有一个ES client的CPU使用率高。所以，我们需要查一下链路，看看ES的service：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root&amp;#64;k8s-master-1 ~]# kubectl get svc -o wide | grep search</span></span>
<span class="line"><span>elasticsearch-client            NodePort    10.96.140.52    &amp;lt;none&amp;gt;        9200:30200/TCP,9300:31614/TCP         34d     app=elasticsearch-client,chart=elasticsearch,heritage=Helm,release=elasticsearch-client</span></span>
<span class="line"><span>elasticsearch-client-headless   ClusterIP   None            &amp;lt;none&amp;gt;        9200/TCP,9300/TCP                     34d     app=elasticsearch-client</span></span>
<span class="line"><span>elasticsearch-data              ClusterIP   10.96.16.151    &amp;lt;none&amp;gt;        9200/TCP,9300/TCP                     7h41m   app=elasticsearch-data,chart=elasticsearch,heritage=Helm,release=elasticsearch-data</span></span>
<span class="line"><span>elasticsearch-data-headless     ClusterIP   None            &amp;lt;none&amp;gt;        9200/TCP,9300/TCP                     7h41m   app=elasticsearch-data</span></span>
<span class="line"><span>elasticsearch-master            ClusterIP   10.96.207.238   &amp;lt;none&amp;gt;        9200/TCP,9300/TCP                     7h41m   app=elasticsearch-master,chart=elasticsearch,heritage=Helm,release=elasticsearch-master</span></span>
<span class="line"><span>elasticsearch-master-headless   ClusterIP   None            &amp;lt;none&amp;gt;        9200/TCP,9300/TCP                     7h41m   app=elasticsearch-master</span></span>
<span class="line"><span>svc-mall-search                 ClusterIP   10.96.27.150    &amp;lt;none&amp;gt;        8081/TCP                              44d     app=svc-mall-search</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]#</span></span></code></pre></div><p>你看，整个namespace中有一个client service（解析出来的是VIP，访问此服务时不会绕过K8s的转发机制），还有一个client-headless service（解析出来的是POD IP，访问这个服务时会绕过K8s的转发机制）。</p><p>接下来，我们查一下为什么会出现访问不均衡的情况。</p><p>通过查看search服务的ES配置，我们看到如下信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  elasticsearch:</span></span>
<span class="line"><span>    rest:</span></span>
<span class="line"><span>      uris: elasticsearch-client:9200</span></span>
<span class="line"><span>      username: elastic</span></span>
<span class="line"><span>      password: admin&amp;#64;123</span></span></code></pre></div><p>看到我们这里是用的elasticsearch-client:9200，我们再来看一下client service的配置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: Service</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  annotations:</span></span>
<span class="line"><span>    meta.helm.sh/release-name: elasticsearch-client</span></span>
<span class="line"><span>    meta.helm.sh/release-namespace: default</span></span>
<span class="line"><span>  creationTimestamp: &#39;2020-12-10T17:34:19Z&#39;</span></span>
<span class="line"><span>  labels:</span></span>
<span class="line"><span>    app: elasticsearch-client</span></span>
<span class="line"><span>    app.kubernetes.io/managed-by: Helm</span></span>
<span class="line"><span>    chart: elasticsearch</span></span>
<span class="line"><span>    heritage: Helm</span></span>
<span class="line"><span>    release: elasticsearch-client</span></span>
<span class="line"><span>  managedFields:</span></span>
<span class="line"><span>    - apiVersion: v1</span></span>
<span class="line"><span>      fieldsType: FieldsV1</span></span>
<span class="line"><span>      fieldsV1:</span></span>
<span class="line"><span>        &#39;f:metadata&#39;: {}</span></span>
<span class="line"><span>        &#39;f:spec&#39;:</span></span>
<span class="line"><span>          &#39;f:ports&#39;: {}</span></span>
<span class="line"><span>      manager: Go-http-client</span></span>
<span class="line"><span>      operation: Update</span></span>
<span class="line"><span>      time: &#39;2020-12-10T17:34:19Z&#39;</span></span>
<span class="line"><span>  name: elasticsearch-client</span></span>
<span class="line"><span>  namespace: default</span></span>
<span class="line"><span>  resourceVersion: &#39;4803428&#39;</span></span>
<span class="line"><span>  selfLink: /api/v1/namespaces/default/services/elasticsearch-client</span></span>
<span class="line"><span>  uid: 457e962e-bee0-49b7-9ec4-ebfbef0fecdd</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  clusterIP: 10.96.140.52</span></span>
<span class="line"><span>  externalTrafficPolicy: Cluster</span></span>
<span class="line"><span>  ports:</span></span>
<span class="line"><span>    - name: http</span></span>
<span class="line"><span>      nodePort: 30200</span></span>
<span class="line"><span>      port: 9200</span></span>
<span class="line"><span>      protocol: TCP</span></span>
<span class="line"><span>      targetPort: 9200</span></span>
<span class="line"><span>    - name: transport</span></span>
<span class="line"><span>      nodePort: 31614</span></span>
<span class="line"><span>      port: 9300</span></span>
<span class="line"><span>      protocol: TCP</span></span>
<span class="line"><span>      targetPort: 9300</span></span>
<span class="line"><span>  selector:</span></span>
<span class="line"><span>    app: elasticsearch-client</span></span>
<span class="line"><span>    chart: elasticsearch</span></span>
<span class="line"><span>    heritage: Helm</span></span>
<span class="line"><span>    release: elasticsearch-client</span></span>
<span class="line"><span>  sessionAffinity: None</span></span>
<span class="line"><span>  type: NodePort</span></span></code></pre></div><p>从上面的配置来看，sessionAffinity也配置为None了，也就是说这个service不以客户端的IP来保持session。因为在这个环境配置中，Type为NodePort，而我们在k8s中配置的转发规则是iptables。所以说，service是依赖iptables的规则来做后端转发的。</p><p>接下来，我们检查一下iptables的转发规则。</p><p>我们先来看iptables中关于ES client的规则：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root&amp;#64;k8s-master-1 ~]# iptables -S KUBE-SERVICES -t nat|grep elasticsearch-client|grep 9200</span></span>
<span class="line"><span>-A KUBE-SERVICES ! -s 10.100.0.0/16 -d 10.96.140.52/32 -p tcp -m comment --comment &quot;default/elasticsearch-client:http cluster IP&quot; -m tcp --dport 9200 -j KUBE-MARK-MASQ</span></span>
<span class="line"><span>-A KUBE-SERVICES -d 10.96.140.52/32 -p tcp -m comment --comment &quot;default/elasticsearch-client:http cluster IP&quot; -m tcp --dport 9200 -j KUBE-SVC-XCX4XZ2WPAE7BUZ4</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]#</span></span></code></pre></div><p>可以看到，service的规则名是KUBE-SVC-XCX4XZ2WPAE7BUZ4，那我们再去查它对应的iptables规则：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root&amp;#64;k8s-master-1 ~]# iptables -S KUBE-SVC-XCX4XZ2WPAE7BUZ4 -t nat</span></span>
<span class="line"><span>-N KUBE-SVC-XCX4XZ2WPAE7BUZ4</span></span>
<span class="line"><span>-A KUBE-SVC-XCX4XZ2WPAE7BUZ4 -m comment --comment &quot;default/elasticsearch-client:http&quot; -j KUBE-SEP-LO263M5QW4XA6E3Q</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]#</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]# iptables -S KUBE-SEP-LO263M5QW4XA6E3Q -t nat</span></span>
<span class="line"><span>-N KUBE-SEP-LO263M5QW4XA6E3Q</span></span>
<span class="line"><span>-A KUBE-SEP-LO263M5QW4XA6E3Q -s 10.100.227.130/32 -m comment --comment &quot;default/elasticsearch-client:http&quot; -j KUBE-MARK-MASQ</span></span>
<span class="line"><span>-A KUBE-SEP-LO263M5QW4XA6E3Q -p tcp -m comment --comment &quot;default/elasticsearch-client:http&quot; -m tcp -j DNAT --to-destination 10.100.227.130:9200</span></span></code></pre></div><p>问题来了，这里好像没有负载均衡的配置（没有probability参数），并且根据iptables规则也只是转发到了一个ES client上。到这里，其实我们也就能理解，为什么在全局监控的时候，我们只看到一个ES client有那么高的CPU使用率，而另一个ES client却一点动静都没有。</p><p>但是，这里的iptables规则并不是自己来配置的，而是在部署k8s的时候自动刷进去的规则。现在只有一条规则了，所以只能转发到一个POD上去。</p><p>那我们就再刷一遍ES的POD，重装一下ES的POD，看k8s自己能不能刷出来负载均衡的iptables规则。重来一遍之后，我们再来看iptables规则：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root&amp;#64;k8s-master-1 ~]# iptables -S KUBE-SVC-XCX4XZ2WPAE7BUZ4 -t nat</span></span>
<span class="line"><span>-N KUBE-SVC-XCX4XZ2WPAE7BUZ4</span></span>
<span class="line"><span>-A KUBE-SVC-XCX4XZ2WPAE7BUZ4 -m comment --comment &quot;default/elasticsearch-client:http&quot; -m statistic --mode random --probability 0.50000000000 -j KUBE-SEP-IFM4L7YNSTSJP4YT</span></span>
<span class="line"><span>-A KUBE-SVC-XCX4XZ2WPAE7BUZ4 -m comment --comment &quot;default/elasticsearch-client:http&quot; -j KUBE-SEP-5RAP6F6FATXC4DFL</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]#</span></span></code></pre></div><p>哟，现在刷出来两条iptables规则了，看来之前在我们不断折腾的部署过程中，ES client一直是有问题的。</p><p>在上面的iptables规则里，那两条iptables的上一条中有一个关键词“——probability 0.50000000000”。我们知道，iptables的匹配规则是从上到下的，既然上一条的匹配是随机0.5，也就是说只有50%的请求会走第一条规则，那下一条自然也是随机0.5了，因为总共只有两条规则嘛。这样一来就均衡了。</p><p>我们再接着做这个接口的压力场景，看到如下信息：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/408592f11401e1yyb1c06ef48f3f8167.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/408592f11401e1yyb1c06ef48f3f8167.png" alt=""></a></p><p>看起来ES client均衡了，对不对？</p><p>它对应的TPS，如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/614e849f975cf983747e080329c0d699.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/614e849f975cf983747e080329c0d699.png" alt=""></a></p><p>明显TPS提升了60左右。</p><p>ES client请求不均衡的问题解决了，现在，我们还要来看一下ES data单节点CPU高的问题。</p><h3 id="es-data-cpu使用率高" tabindex="-1">ES Data CPU使用率高 <a class="header-anchor" href="#es-data-cpu使用率高" aria-label="Permalink to &quot;ES Data CPU使用率高&quot;">​</a></h3><ul><li><strong>第一阶段：加一个CPU</strong></li></ul><p>在TPS提升之后，我们再来看一下全局监控数据。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/2ec7cce680e81f57717c642cf7834279.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/2ec7cce680e81f57717c642cf7834279.png" alt=""></a></p><p>看起来比一开始好多了。基于前面分析ES client的经验，我们就先来查一下ES data的iptables规则：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-- 查看下有哪些ES data的POD</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]# kubectl get pods -o wide | grep data</span></span>
<span class="line"><span>elasticsearch-data-0                        1/1     Running   0          10h     10.100.18.197    k8s-worker-5   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>elasticsearch-data-1                        1/1     Running   0          10h     10.100.5.5       k8s-worker-7   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>elasticsearch-data-2                        1/1     Running   0          10h     10.100.251.67    k8s-worker-9   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 查看ES data对应的iptables规则</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]# iptables -S KUBE-SERVICES -t nat|grep elasticsearch-data</span></span>
<span class="line"><span>-A KUBE-SERVICES ! -s 10.100.0.0/16 -d 10.96.16.151/32 -p tcp -m comment --comment &quot;default/elasticsearch-data:http cluster IP&quot; -m tcp --dport 9200 -j KUBE-MARK-MASQ</span></span>
<span class="line"><span>-A KUBE-SERVICES -d 10.96.16.151/32 -p tcp -m comment --comment &quot;default/elasticsearch-data:http cluster IP&quot; -m tcp --dport 9200 -j KUBE-SVC-4LU6GV7CN63XJXEQ</span></span>
<span class="line"><span>-A KUBE-SERVICES ! -s 10.100.0.0/16 -d 10.96.16.151/32 -p tcp -m comment --comment &quot;default/elasticsearch-data:transport cluster IP&quot; -m tcp --dport 9300 -j KUBE-MARK-MASQ</span></span>
<span class="line"><span>-A KUBE-SERVICES -d 10.96.16.151/32 -p tcp -m comment --comment &quot;default/elasticsearch-data:transport cluster IP&quot; -m tcp --dport 9300 -j KUBE-SVC-W4QKPGOO4JGYQZDQ</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 查看9200（外部通信）对应的规则</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]# iptables -S KUBE-SVC-4LU6GV7CN63XJXEQ -t nat</span></span>
<span class="line"><span>-N KUBE-SVC-4LU6GV7CN63XJXEQ</span></span>
<span class="line"><span>-A KUBE-SVC-4LU6GV7CN63XJXEQ -m comment --comment &quot;default/elasticsearch-data:http&quot; -m statistic --mode random --probability 0.33333333349 -j KUBE-SEP-ZHLKOYKJY5GV3ZVN</span></span>
<span class="line"><span>-A KUBE-SVC-4LU6GV7CN63XJXEQ -m comment --comment &quot;default/elasticsearch-data:http&quot; -m statistic --mode random --probability 1 -j KUBE-SEP-6ILKZEZS3TMCB4VJ</span></span>
<span class="line"><span>-A KUBE-SVC-4LU6GV7CN63XJXEQ -m comment --comment &quot;default/elasticsearch-data:http&quot; -j KUBE-SEP-JOYLBDPA3LNXKWUK</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 查看以上三条规则的转发目标</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]# iptables -S KUBE-SEP-ZHLKOYKJY5GV3ZVN -t nat</span></span>
<span class="line"><span>-N KUBE-SEP-ZHLKOYKJY5GV3ZVN</span></span>
<span class="line"><span>-A KUBE-SEP-ZHLKOYKJY5GV3ZVN -s 10.100.18.197/32 -m comment --comment &quot;default/elasticsearch-data:http&quot; -j KUBE-MARK-MASQ</span></span>
<span class="line"><span>-A KUBE-SEP-ZHLKOYKJY5GV3ZVN -p tcp -m comment --comment &quot;default/elasticsearch-data:http&quot; -m tcp -j DNAT --to-destination 10.100.18.197:9200</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]# iptables -S KUBE-SEP-6ILKZEZS3TMCB4VJ -t nat</span></span>
<span class="line"><span>-N KUBE-SEP-6ILKZEZS3TMCB4VJ</span></span>
<span class="line"><span>-A KUBE-SEP-6ILKZEZS3TMCB4VJ -s 10.100.251.67/32 -m comment --comment &quot;default/elasticsearch-data:http&quot; -j KUBE-MARK-MASQ</span></span>
<span class="line"><span>-A KUBE-SEP-6ILKZEZS3TMCB4VJ -p tcp -m comment --comment &quot;default/elasticsearch-data:http&quot; -m tcp -j DNAT --to-destination 10.100.251.67:9200</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]# iptables -S KUBE-SEP-JOYLBDPA3LNXKWUK -t nat</span></span>
<span class="line"><span>-N KUBE-SEP-JOYLBDPA3LNXKWUK</span></span>
<span class="line"><span>-A KUBE-SEP-JOYLBDPA3LNXKWUK -s 10.100.5.5/32 -m comment --comment &quot;default/elasticsearch-data:http&quot; -j KUBE-MARK-MASQ</span></span>
<span class="line"><span>-A KUBE-SEP-JOYLBDPA3LNXKWUK -p tcp -m comment --comment &quot;default/elasticsearch-data:http&quot; -m tcp -j DNAT --to-destination 10.100.5.5:9200</span></span>
<span class="line"><span>[root&amp;#64;k8s-master-1 ~]</span></span></code></pre></div><p>Everything is perfect!！规则很合理。ES Data总共有三个pod，从逻辑上来看，它们各占了三分之一。</p><p>在前面的ES client分析中，我们讲到，第一个POD是0.5，下一条自然也只剩下0.5，这很容易理解。现在，ES data的部分有三条iptables规则，我们来简单说明一下。</p><blockquote><p>通常我们理解的iptables就是一个防火墙。不过，要是从根本上来讲，它不算是一个防火墙，只是一堆规则列表，而通过iptables设计的规则列表，请求会对应到netfilter框架中去，而这个netfilter框架，才是真正的防火墙。其中，netfilter是处于内核中的，iptables就只是一个用户空间上的配置工具而已。</p></blockquote><blockquote><p>我们知道iptables有四表五链。四表是：fileter表（负责过滤）、nat表（负责地址转换）、mangle表（负责解析）、raw表（关闭nat表上启用的连接追踪）；五链是：prerouting链（路由前）、input链（输入规则）、forward链（转发规则）、output链（输出规则）、postrouting链（路由后）。</p></blockquote><blockquote><p>而在这一部分，我们主要是看nat表以及其上的链。对于其他的部分，如果你想学习，可自行查阅iptables相关知识。毕竟，我还时刻记得自己写的是一个性能专栏，而不是计算机基础知识专栏，哈哈。</p></blockquote><p>从上面的信息可以看到，我们的这个集群中有三个ES data服务，对应着三条转发规则，其中，第一条规则的匹配比例是：0.33333333349；第二条比例：0.50000000000；第三条是1。而这三条转发规则对应的POD IP和端口分别是：10.100.18.197:9200、10.100.251.67:9200、10.100.5.5:9200，这也就意味着，通过这三条iptables规则可以实现负载均衡，画图理解如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/5e9c08e967c62d9e9a84084d8c2de888.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/5e9c08e967c62d9e9a84084d8c2de888.jpg" alt=""></a></p><p>我们假设有30个请求进来，那ES Data 0上就会有30x0.33333333349=10个请求；对于剩下的20个请求，在ES Data 1上就会有20x0.50000000000=10个请求；而最后剩下的10个请求，自然就到了ES Data 2上。这是一个非常均衡的逻辑，只是在iptables规则中，我看着这几个数据比例，实在是觉得别扭。</p><p>既然明白了这个逻辑，下面我们还是把查询商品接口的场景压起来看一下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/06eb3b24a57226cd9a6717cd1e3f6049.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/06eb3b24a57226cd9a6717cd1e3f6049.png" alt=""></a></p><p>从数据上来看，经常会出现ES data 某个节点消耗CPU高的情况。可是，对应到我们前面看到的全局worker监控界面中，并没有哪个worker的CPU很高。所以，在这里，我们要查一下ES Data中的cgroup配置，看它的限制是多少。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/8yyd469d83c9a346aff8c659f6c4ae3c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/8yyd469d83c9a346aff8c659f6c4ae3c.png" alt=""></a></p><p>也就是说，ES data的每个POD都是配置了一颗CPU，难怪CPU使用率动不动就红了。</p><p>还有一点你要记住，前面我们在查看data列表的时候发现，ES data 0 在worker-5上，ES data 1 在worker-7上，ES data 2 在worker-9上。而我们现在看到的却是，它们都各自分到了一个CPU。既然如此，那我们就再添加一个CPU，然后再回去看一下worker-5/7/9的反应。为什么只加一个CPU呢？因为从worker-7上来看，现在的CPU使用率已经在50%左右了，要是加多了，我怕它吃不消。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/f57acfca05yy43bd882a57404ea50d01.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/f57acfca05yy43bd882a57404ea50d01.png" alt=""></a></p><p>看一下压力场景执行的效果：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/299bbd39759ca90bdc4953334bc0c39c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/299bbd39759ca90bdc4953334bc0c39c.png" alt=""></a></p><p>似乎……不怎么样？TPS并没有增加。</p><ul><li><strong>第二阶段：加副本</strong></li></ul><p>我们再看加了CPU之后的全局POD监控：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/925d14923a3bfac75ef84b9b21622294.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/925d14923a3bfac75ef84b9b21622294.png" alt=""></a></p><p>还是只有一个ES data的CPU使用率高，所以我想查一下ES中的数据分布。因为负载均衡的问题解决了，并且知道有三个ES data节点。现在我们就要知道是不是每个节点都被访问到了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pms                               0 p 10.100.18.199 _w   32   17690 18363   6.7mb  7820 true  true  8.5.1 false</span></span>
<span class="line"><span>pms                               0 p 10.100.18.199 _15  41    2110     0 465.7kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 p 10.100.18.199 _16  42   21083 30255   9.5mb  5900 true  true  8.5.1 false</span></span>
<span class="line"><span>pms                               0 p 10.100.18.199 _17  43    2572     0   568kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 p 10.100.18.199 _18  44    1403     0 322.9kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 p 10.100.18.199 _19  45    1856     0 414.1kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 p 10.100.18.199 _1a  46    1904     0   423kb  5500 true  true  8.5.1 true</span></span></code></pre></div><p>为啥数据都在一个节点上（都是10.100.18.199）？看起来只有一个数据副本的原因了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>green open pms                                            A--6O32bQaSBrJPJltOLHQ 1 0   48618 48618  55.1mb  18.3mb</span></span></code></pre></div><p>所以，我们先把副本数加上去，因为我们有三个data节点，所以这里加三个副本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUT /pms/_settings</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;number_of_replicas&quot;: 3</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>我们再次查看ES中的数据分布，如下所示：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pms                               0 r 10.100.18.200 _w   32   17690 18363   6.7mb  7820 true  true  8.5.1 false</span></span>
<span class="line"><span>pms                               0 r 10.100.18.200 _15  41    2110     0 465.7kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 r 10.100.18.200 _16  42   21083 30255   9.5mb  5900 true  true  8.5.1 false</span></span>
<span class="line"><span>pms                               0 r 10.100.18.200 _17  43    2572     0   568kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 r 10.100.18.200 _18  44    1403     0 322.9kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 r 10.100.18.200 _19  45    1856     0 414.1kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 r 10.100.18.200 _1a  46    1904     0   423kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 p 10.100.251.69 _w   32   17690 18363   6.7mb  7820 true  true  8.5.1 false</span></span>
<span class="line"><span>pms                               0 p 10.100.251.69 _15  41    2110     0 465.7kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 p 10.100.251.69 _16  42   21083 30255   9.5mb  5900 true  true  8.5.1 false</span></span>
<span class="line"><span>pms                               0 p 10.100.251.69 _17  43    2572     0   568kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 p 10.100.251.69 _18  44    1403     0 322.9kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 p 10.100.251.69 _19  45    1856     0 414.1kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 p 10.100.251.69 _1a  46    1904     0   423kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 r 10.100.140.10 _w   32   17690 18363   6.7mb  7820 true  true  8.5.1 false</span></span>
<span class="line"><span>pms                               0 r 10.100.140.10 _15  41    2110     0 465.7kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 r 10.100.140.10 _16  42   21083 30255   9.5mb  5900 true  true  8.5.1 false</span></span>
<span class="line"><span>pms                               0 r 10.100.140.10 _17  43    2572     0   568kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 r 10.100.140.10 _18  44    1403     0 322.9kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 r 10.100.140.10 _19  45    1856     0 414.1kb  5500 true  true  8.5.1 true</span></span>
<span class="line"><span>pms                               0 r 10.100.140.10 _1a  46    1904     0   423kb  5500 true  true  8.5.1 true</span></span></code></pre></div><p>我们接着压起来，看看POD的资源：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/11ayy743164f36a8d0b04bc76af52ccc.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/11ayy743164f36a8d0b04bc76af52ccc.png" alt=""></a></p><p>现在看着是不是开心多了？data节点的CPU都用起来了。</p><p>我们再看一下worker的资源：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root&amp;#64;k8s-master-1 ~]# kubectl get pods -o wide | grep data</span></span>
<span class="line"><span>elasticsearch-data-0                        1/1     Running   0          16m     10.100.18.199    k8s-worker-5   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>elasticsearch-data-1                        1/1     Running   0          17m     10.100.251.68    k8s-worker-9   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span>
<span class="line"><span>elasticsearch-data-2                        1/1     Running   0          18m     10.100.140.9     k8s-worker-2   &amp;lt;none&amp;gt;           &amp;lt;none&amp;gt;</span></span></code></pre></div><p>现在ES Data的POD分布到2、5、9三这个worker上去了，我们查看下全局监控：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/53a522a2754d7fcea550fde05cd791b1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/53a522a2754d7fcea550fde05cd791b1.png" alt=""></a></p><p>嗯，不错，ES data的POD把资源用起来了。其实这里要想继续调，还可以把CPU加大，ES本来就是吃CPU、内存的大户。不过，我们前面在配置的时候，给ES data的CPU也确实太小了。这个问题，并不是我故意设计出来的，而是当时在部署的时候，没考虑到这些。</p><p>最后，我们来看优化后的效果：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/1fb93ff5yycfc2bb6049244820e73b24.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%AB%98%E6%A5%BC%E7%9A%84%E6%80%A7%E8%83%BD%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98%E8%AF%BE/images/366020/1fb93ff5yycfc2bb6049244820e73b24.png" alt=""></a></p><p>呀呀呀，你看TPS压都压不住呀，很快涨到900左右了！这个优化结果很好。</p><p>现在回过头来看第一个阶段，我们加CPU没有效果，主要还是因为副本数量太少。其实，在ES的优化中，还有很多细节可以玩。只不过，在我们这个课程中，我希望给你的是一个整体的分析思路和逻辑，而不是纠结于每个细节上的参数。所以，在这里，我们就不再说具体参数的调整了。</p><p>如果你想在ES上做更多的优化，可以在分析完业务之后，确定一下ES的架构、数据索引、分片等信息，然后再来设计一个合理的ES部署。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在这节课中，我们看到APM工具也有无能为力的地方。所以说，当我们分析到一个具体组件之后，要想再往下分析，就得靠自己的技术功底了。</p><p>在出现请求不均衡的时候，我们一定要先去看负载均衡的逻辑有没有问题。当看到ES client不均衡时，我们去看了iptables的原理，在发现iptables只有一个转发规则的时候，接下来要做的当然就是重刷转发规则了。</p><p>在ES client转发均衡了之后，我们在ES data单节点上又看到CPU使用率过高。由于ES data在POD当中，我们自然就要想到去看cgroup的限制。</p><p>而在添加了CPU之后，我们发现TPS并没有提高，这时候就要去看ES的逻辑了。ES的强大之处就在于多副本多分片的查询能力，所以，我们增加了副本之后，CPU就用起来了，这是一个合理的优化结果，TPS也自然提高了。</p><p>经过一系列的动作，我们终于把资源给用起来了。这也是我一直在强调的， <strong>性能优化第一个阶段的目标，就是把资源给用起来，然后再考虑更细节的优化</strong>。</p><h2 id="课后作业" tabindex="-1">课后作业 <a class="header-anchor" href="#课后作业" aria-label="Permalink to &quot;课后作业&quot;">​</a></h2><p>最后，我给你留两道题，请你思考一下：</p><ol><li>当负载出现不均衡时，主要的分析方向是什么？</li><li>什么时候才需要去看组件内部的实现逻辑？</li></ol><p>记得在留言区和我讨论、交流你的想法，每一次思考都会让你更进一步。</p><p>如果你读完这篇文章有所收获，也欢迎你分享给你的朋友，共同学习进步。我们下一讲再见！</p>`,131)])])}const u=s(p,[["render",i]]);export{h as __pageData,u as default};
